package com.hau.exam.application.service;import com.hau.exam.application.port.out.ExamMatrixRepository;import com.hau.exam.domain.exception.*;import com.hau.exam.domain.model.*;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class MatrixService{private final ExamMatrixRepository repo;private final Clock clock;public MatrixService(ExamMatrixRepository r,Clock c){repo=r;clock=c;}@Transactional public ExamMatrix save(UUID id,String name,String faculty,UUID subject,int total,List<ExamMatrixRule>rules,Actor actor){scope(actor,faculty);Instant now=Instant.now(clock);ExamMatrix old=id==null?null:get(id,actor);return repo.save(new ExamMatrix(id==null?UUID.randomUUID():id,name,faculty,subject,total,rules,actor.userId(),old==null?now:old.createdAt(),now));}@Transactional(readOnly=true)public ExamMatrix get(UUID id,Actor a){var m=repo.findById(id).orElseThrow(()->new NotFoundException("Exam matrix not found"));scope(a,m.facultyId());return m;}@Transactional(readOnly=true)public List<ExamMatrix>list(Actor a){role(a);return repo.findByFaculty(a.facultyId());}public void validate(UUID id,Actor a){get(id,a);}static void scope(Actor a,String f){role(a);if(a.facultyId()==null||!a.facultyId().equals(f))throw new ForbiddenException("Resource is outside faculty scope");}static void role(Actor a){if(a.role()!=Role.SUBJECT_ADMIN)throw new ForbiddenException("SUBJECT_ADMIN role is required");}}
